import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../../../core/di/catalog_providers.dart';import '../../../core/presentation/catalog_cards.dart';class PortfolioScreen extends ConsumerWidget{const PortfolioScreen({super.key});@override Widget build(BuildContext c,WidgetRef r){final a=r.watch(portfolioProvider(null));return Scaffold(appBar:AppBar(title:const Text('Success Stories')),body:a.when(data:(items)=>items.isEmpty?const Center(child:Text('No stories available')):ListView.builder(padding:const EdgeInsets.all(12),itemCount:items.length,itemBuilder:(_,i){final x=items[i] as Map<String,dynamic>;return CatalogCard(item:x,label:'Story',onTap:()=>c.push('/portfolio/${x['id']}'));}),loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('$e'))));}}
